struct bio *bio_map_user_iovec(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    struct page **pages;
    size_t nr_pages;
    ssize_t ret;

    nr_pages = iov_iter_npages(iter, INT_MAX);
    if (nr_pages == 0)
        return ERR_PTR(-EINVAL);

    pages = kvmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages)
        return ERR_PTR(-ENOMEM);

    ret = iov_iter_get_pages(iter, pages, LLONG_MAX, nr_pages, NULL);
    if (ret < 0) {
        kvfree(pages);
        return ERR_PTR(ret);
    }

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio) {
        iov_iter_revert(iter, ret);
        kvfree(pages);
        return ERR_PTR(-ENOMEM);
    }

    bio_set_pages(bio, pages, ret >> PAGE_SHIFT);

    bio->bi_private = NULL;
    bio->bi_flags |= BIO_USET;

    return bio;
}

struct bio *bio_map_user_iovec(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    struct bio_vec *bvec;
    unsigned int nr_vecs;
    int i, npages;
    struct page **pages;
    ssize_t bytes;
    int ret;

    bytes = iov_iter_count(iter);
    if (!bytes)
        return ERR_PTR(-EINVAL);

    npages = iov_iter_npages(iter, BIO_MAX_PAGES);
    if (npages <= 0 || npages > BIO_MAX_PAGES)
        return ERR_PTR(-EINVAL);

    pages = kvmalloc_array(npages, sizeof(struct page *), gfp_mask);
    if (!pages)
        return ERR_PTR(-ENOMEM);

    nr_vecs = iov_iter_get_pages(iter, pages, bytes, npages, &ret);
    if (ret < 0) {
        kfree(pages);
        return ERR_PTR(ret);
    }

    bio = bio_alloc(gfp_mask, nr_vecs);
    if (!bio) {
        kfree(pages);
        return ERR_PTR(-ENOMEM);
    }

    bio->bi_private = pages;
    bio->bi_end_io = NULL;
    bio->bi_flags |= (1 << BIO_USER_MAPPED);

    for (i = 0; i < nr_vecs; i++) {
        struct page *page = pages[i];
        size_t len = bio_iovec_idx(bio, i).bv_len;

        bvec = &bio->bi_iovec[i];
        bvec->bv_page = page;
        bvec->bv_len = len;
        bvec->bv_offset = iter->iov[i].iov_base - page_address(page);
    }

    bio_set_pages(bio, pages, nr_vecs, bytes);
    bio->bi_sector = 0;
    bio->bi_bdev = NULL;

    return bio;
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    unsigned long nr_pages;
    int i, j;
    size_t total_len;
    struct page **pages;
    struct bio_vec *bvec;
    ssize_t ret;

    total_len = iov_iter_count(iter);
    if (!total_len)
        return ERR_PTR(-EINVAL);

    nr_pages = iov_iter_npages(iter, BIO_MAX_PAGES);
    if (!nr_pages)
        return ERR_PTR(-EINVAL);

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages)
        return ERR_PTR(-ENOMEM);

    nr_pages = iov_iter_get_pages(iter, pages, total_len, BIO_MAX_PAGES, NULL);
    if (nr_pages <= 0) {
        kfree(pages);
        return ERR_PTR(nr_pages ? : -EFAULT);
    }

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio) {
        iov_iter_revert(iter, total_len);
        kfree(pages);
        return ERR_PTR(-ENOMEM);
    }

    bio->bi_iter.bi_size = total_len;
    bio->bi_io_vec = bio->bi_inline_vecs;

    for (i = 0, j = 0; i < nr_pages; i++) {
        struct page *page = pages[i];
        size_t len = PAGE_SIZE;
        if (i == nr_pages - 1)
            len = total_len - j;

        bio->bi_io_vec[i].bv_page = page;
        bio->bi_io_vec[i].bv_len = len;
        bio->bi_io_vec[i].bv_offset = j;
        j += len;
    }

    kfree(pages);

    bio->bi_flags |= (1 << BIO_USER_MAPPED);

    return bio;
}

struct bio *bio_map_user_iovec(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio;
    struct page **pages;
    unsigned int nr_pages;
    ssize_t ret;

    ret = iov_iter_get_pages_alloc(iter, &pages, iov_iter_count(iter), BIO_MAX_PAGES, &nr_pages);
    if (ret < 0)
        return ERR_PTR(ret);

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio) {
        kfree(pages);
        return ERR_PTR(-ENOMEM);
    }

    bio_set_pages(bio, pages, nr_pages, ret);
    bio->bi_iter = *iter;
    bio->bi_flag |= BIO_USER_MAPPED;

    return bio;
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    unsigned long nr_pages;
    ssize_t ret;

    ret = iov_iter_npages(iter, BIO_MAX_PAGES);
    if (ret < 0)
        return ERR_PTR(ret);
    nr_pages = ret;

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    ret = bio_map_user_iov(bio, iter, gfp_mask);
    if (IS_ERR(ret)) {
        bio_put(bio);
        return ret;
    }

    bio->bi_private = (void *)1; /* flag indicating user-mapped bio */
    return bio;
}
